// models/Salary.js
const db = require('../config/db');  // Assuming this is your DB connection file

// Function to get salary details of an employee for a specific month and year
const getSalaryDetails = async (employee_id, year, month) => {
  const query = `
    SELECT * FROM employee_salaries
    WHERE employee_id = ? AND year = ? AND month = ?
  `;
  const [rows] = await db.execute(query, [employee_id, year, month]);
  return rows[0]; // Return the first record (should be unique)
};

// Function to add salary details for an employee
const addSalaryDetails = async (employee_id, month, year, salary_per_day, days_worked, expense) => {
  const earned = salary_per_day * days_worked;
  const query = `
    INSERT INTO employee_salaries (employee_id, month, year, salary_per_day, days_worked, expense, earned)
    VALUES (?, ?, ?, ?, ?, ?, ?)
  `;
  await db.execute(query, [employee_id, month, year, salary_per_day, days_worked, expense, earned]);
};

// Function to get the total salary earned and remaining amount for an employee in a given year
const getAnnualSalaryDetails = async (employee_id, year) => {
  const query = `
    SELECT SUM(earned) AS total_earned, SUM(expense) AS total_expense 
    FROM employee_salaries
    WHERE employee_id = ? AND year = ?
  `;
  const [rows] = await db.execute(query, [employee_id, year]);
  const totalEarned = rows[0].total_earned || 0;
  const totalExpense = rows[0].total_expense || 0;
  const remainingAmount = totalEarned - totalExpense;

  return { totalEarned, totalExpense, remainingAmount };
};

module.exports = {
  getSalaryDetails,
  addSalaryDetails,
  getAnnualSalaryDetails
};
